package io.github.diodeme.ji.remote;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.file.Files;
import java.security.KeyPairGenerator;
import java.security.MessageDigest;
import java.security.Signature;
import java.time.Duration;
import java.util.ArrayList;
import java.util.Base64;
import java.util.HexFormat;
import java.util.List;
import java.util.Optional;
import org.junit.jupiter.api.Test;

final class RemoteHostInstallerTest {
    @Test
    void verifiesEd25519SignatureAndArchiveHash() throws Exception {
        var archive = Files.createTempFile("ji-host-bundle-", ".tar.gz");
        Files.writeString(archive, "synthetic archive");
        var pair = KeyPairGenerator.getInstance("Ed25519").generateKeyPair();
        String hash = HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(archive)));
        var unsigned = new BundleManifest("1.0.0", "linux", "x64", hash, "Ed25519", "pending");
        Signature signer = Signature.getInstance("Ed25519");
        signer.initSign(pair.getPrivate());
        signer.update(BundleVerifier.signedPayload(unsigned));
        var signed = new BundleManifest(unsigned.version(), unsigned.os(), unsigned.architecture(),
                unsigned.archiveSha256(), unsigned.signatureAlgorithm(), Base64.getEncoder().encodeToString(signer.sign()));

        new BundleVerifier().verify(signed, archive, pair.getPublic());
        Files.writeString(archive, "tampered");
        assertThrows(IllegalArgumentException.class,
                () -> new BundleVerifier().verify(signed, archive, pair.getPublic()));
    }

    @Test
    void installsWithAgentWithoutSudoAndUsesVersionedAtomicActivation() throws Exception {
        var runner = new RecordingRunner(false);
        var installer = new RemoteHostInstaller(runner);
        var target = new SshTarget("tester", "host.example", 22, Optional.empty());
        var platform = installer.probe(target);
        var archive = Files.createTempFile("ji-host-bundle-", ".tar.gz");
        var manifest = new BundleManifest("1.2.3", "linux", "x64", "a".repeat(64), "Ed25519", "c2ln");
        RemoteHostInstaller.InstallResult result = installer.install(target, manifest, archive, platform);
        String joined = runner.commands.stream().flatMap(List::stream).reduce("", (left, right) -> left + " " + right);

        assertEquals("1.2.3", result.version());
        assertFalse(joined.contains("sudo"));
        assertFalse(joined.contains(" -i "));
        assertTrue(joined.contains("/home/tester/.local/share/ji-host/versions/1.2.3"));
        assertTrue(joined.contains("mv -Tf"));
        assertTrue(joined.contains("127.0.0.1"));
        assertTrue(joined.contains("systemctl --user"));
        assertTrue(joined.contains("--health-check"));
    }

    @Test
    void explicitIdentityIsOnlyPassedAsAPathAndReadinessFailureRollsBack() throws Exception {
        var runner = new RecordingRunner(true);
        var installer = new RemoteHostInstaller(runner);
        var target = new SshTarget("tester", "host.example", 2222,
                Optional.of(java.nio.file.Path.of("C:/keys/external.pem")));
        var archive = Files.createTempFile("ji-host-bundle-", ".tar.gz");
        var manifest = new BundleManifest("2.0.0", "linux", "x64", "b".repeat(64), "Ed25519", "c2ln");

        assertThrows(IllegalStateException.class, () -> installer.install(target, manifest, archive,
                new RemoteHostInstaller.Platform("linux", "x64", "/home/tester")));
        List<String> flat = runner.commands.stream().flatMap(List::stream).toList();
        assertTrue(flat.contains("-i"));
        assertTrue(flat.stream().anyMatch(value -> value.endsWith("external.pem")));
        assertTrue(runner.commands.stream().flatMap(List::stream)
                .anyMatch(value -> value.contains(".rollback")));
    }

    @Test
    void tunnelBindsOnlyClientAndRemoteLoopback() {
        var installer = new RemoteHostInstaller((command, timeout) -> new ProcessRunner.Result(0, "", ""));
        var tunnel = installer.openTunnel(new SshTarget("tester", "host.example", 22, Optional.empty()),
                18091, 18091);
        assertTrue(tunnel.command().contains("18091:127.0.0.1:18091"));
        assertFalse(tunnel.command().stream().anyMatch(value -> value.contains("0.0.0.0")));
    }

    private static final class RecordingRunner implements ProcessRunner {
        private final List<List<String>> commands = new ArrayList<>();
        private final boolean failActivation;

        private RecordingRunner(boolean failActivation) { this.failActivation = failActivation; }

        @Override
        public Result run(List<String> command, Duration timeout) {
            commands.add(command);
            String joined = String.join(" ", command);
            if (joined.contains("uname -s")) return new Result(0, "Linux\nx86_64\n/home/tester\n", "");
            if (failActivation && joined.contains("--health-check")) return new Result(1, "", "failed");
            return new Result(0, "", "");
        }
    }
}
